        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name pod, metric, time_bucket(INTERVAL 30 SECOND, time) b, min(value) mn, max(value) mx FROM abnormal_metrics WHERE metric IN ('k8s.container.ready','k8s.container.restarts') AND attr_k8s_pod_name LIKE 'search-%' GROUP BY ALL ORDER BY b, metric", "claim": "search pod stayed not-ready (ready=0) and its restart count climbed from 6 to 8 during the window."},
        {"kind": "trace", "sql": "SELECT time_bucket(INTERVAL 1 MINUTE, time) b, service_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' GROUP BY ALL ORDER BY b", "claim": "Frontend /hotels server spans return HTTP 500 in nearly every minute of the abnormal window."}
      ]
    },
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, count(*) n, max(time) last_seen FROM abnormal_traces WHERE service_name='profile' AND attr_span_kind='Server' GROUP BY ALL", "claim": "Profile produced no server spans in the abnormal window; normal period had 1581."},
        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name pod, metric, time_bucket(INTERVAL 30 SECOND, time) b, min(value) mn, max(value) mx FROM abnormal_metrics WHERE metric IN ('k8s.container.ready','k8s.container.restarts') AND attr_k8s_pod_name LIKE 'profile-%' GROUP BY ALL ORDER BY b, metric", "claim": "profile pod stayed not-ready and restarted repeatedly, with restart count rising from 6 to 8."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name='profile.Profile/GetProfiles' GROUP BY ALL", "claim": "Frontend's calls to profile.Profile/GetProfiles failed with Error status in the abnormal window."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
