        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name='search.Search/Nearby' GROUP BY ALL", "claim": "Frontend's search.Search/Nearby client calls all errored after search went down, driving the /hotels 500s."}
